urlset:
{% for url in urlset %}

    {{ url.location }}
{% if url.lastmod %}
    {# Google requires W3C Datetime (YYYY-MM-DD or ISO-8601 with T), not Python's " " datetime dump. #}
    {{ url.lastmod.isoformat() }}
{% endif %}
{% if url.changefreq %}
    {{ url.changefreq }}
{% endif %}
{% if url.priority %}
    {{ url.priority }}
{% endif %}

{% endfor %}
